import{_ as a,o as d,c as e,ag as r}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"安装前准备","description":"安装 InduFrame 中心前，核对服务器、磁盘余量、访问地址、证书和管理员信息。","frontmatter":{"title":"安装前准备","description":"安装 InduFrame 中心前，核对服务器、磁盘余量、访问地址、证书和管理员信息。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/prepare.md","filePath":"zh/安装运维/安装前准备.md"}'),o={name:"zh/installation/prepare.md"};function i(l,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="安装前准备" tabindex="-1">安装前准备 <a class="header-anchor" href="#安装前准备" aria-label="Permalink to &quot;安装前准备&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>准备一台适合安装 InduFrame 中心的服务器和完整安装包，明确两个访问入口及管理员信息，让后续安装向导能够一次填写完整。</p><h2 id="角色与环境前提" tabindex="-1">角色与环境前提 <a class="header-anchor" href="#角色与环境前提" aria-label="Permalink to &quot;角色与环境前提&quot;">​</a></h2><p>由负责服务器的安装人员完成本页检查，并与平台管理员确认访问地址和账号交接方式。安装人员需要服务器的系统管理权限，能够在交互终端中使用 <code>sudo</code>。</p><p>本指南以采用 systemd 的 Linux amd64 专用虚拟机和自签名证书为基础。中心安装包仅用于 Linux，按 amd64、arm64 分别提供；实际发行版、系统配置、arm64 及自带证书环境需单独验收。Windows 不能使用本中心安装包，独立节点能力以交付确认范围为准。</p><h2 id="操作入口" tabindex="-1">操作入口 <a class="header-anchor" href="#操作入口" aria-label="Permalink to &quot;操作入口&quot;">​</a></h2><p>在目标服务器的终端核对环境，在使用者的浏览器所在网络核对访问条件。准备供应方交付的完整中心安装包，后续从包内的 <code>install.sh</code> 开始安装。</p><h2 id="准备步骤与字段" tabindex="-1">准备步骤与字段 <a class="header-anchor" href="#准备步骤与字段" aria-label="Permalink to &quot;准备步骤与字段&quot;">​</a></h2><h3 id="_1-核对服务器和磁盘" tabindex="-1">1. 核对服务器和磁盘 <a class="header-anchor" href="#_1-核对服务器和磁盘" aria-label="Permalink to &quot;1. 核对服务器和磁盘&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>要求</th></tr></thead><tbody><tr><td>系统与架构</td><td>使用 systemd 管理系统服务的 Linux amd64，安装包与服务器架构一致</td></tr><tr><td>服务器用途</td><td>明确用于本次中心安装；已有其他服务时，先由维护人员确认是否适合共用</td></tr><tr><td>系统权限</td><td>安装账号具备 <code>sudo</code> 权限，可以在终端完成交互确认</td></tr><tr><td>系统盘</td><td>可用空间同时满足至少 30 GiB、至少总容量的 20%</td></tr><tr><td>独立数据盘</td><td>平台运行数据如存放在独立磁盘，该盘也须同时满足至少 30 GiB、至少 20% 可用空间</td></tr><tr><td>网络</td><td>具备可用的 IPv4 网络，服务器和使用者之间的访问路径已确认</td></tr></tbody></table><p>磁盘要求是安装与运行时必须保留的余量，不是工程规模或历史数据容量的保证。请另外为业务数据、工程文件和后续增长规划空间。</p><p>离线安装包也可能需要服务器已有必需的系统网络组件。没有外网时，应由维护人员提前准备；不要把“离线包”理解为任何系统都无需准备。</p><h3 id="_2-确定访问地址和端口" tabindex="-1">2. 确定访问地址和端口 <a class="header-anchor" href="#_2-确定访问地址和端口" aria-label="Permalink to &quot;2. 确定访问地址和端口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>准备内容</th></tr></thead><tbody><tr><td>公共访问地址或域名</td><td>组织成员浏览器能够访问的服务器地址；使用域名时，确认它已正确解析</td></tr><tr><td>公共访问端口</td><td>默认 <code>443</code>；当前公共入口固定使用 HTTPS</td></tr><tr><td>管理入口</td><td>地址由安装器自动选择服务器内网地址，端口默认 <code>18100</code>；安装结束后保存终端给出的完整地址</td></tr><tr><td>访问范围</td><td>组织成员能访问公共入口；平台管理员能从管理网络访问管理入口</td></tr></tbody></table><p>两个端口应互不相同，也不能被其他服务占用。防火墙和网络访问规则由服务器维护人员核对。管理入口使用终端提供的内网 HTTP 地址，并包含 <code>/admin/</code>，不要把公共入口的地址直接当作管理入口。</p><h3 id="_3-准备程序存放位置和安装包" tabindex="-1">3. 准备程序存放位置和安装包 <a class="header-anchor" href="#_3-准备程序存放位置和安装包" aria-label="Permalink to &quot;3. 准备程序存放位置和安装包&quot;">​</a></h3><p>取得适用于服务器的安装包，上传到服务器并解压。安装和更新均运行 <code>install.sh</code>，具体步骤见<a href="/induframe-docs/zh/installation/quick-install.html">快速安装</a>。安装包中也提供了这份说明，离线时可以阅读。</p><p>安装向导填写的是程序目录的<strong>父目录</strong>：输入默认的 <code>/opt</code> 后，程序放在 <code>/opt/induframe</code>。使用其他位置时填写可写的绝对目录，不要选择安装包内部或经过符号链接的路径。更改程序存放位置不会自动更改平台运行数据所在磁盘。</p><h3 id="_4-准备证书和账号" tabindex="-1">4. 准备证书和账号 <a class="header-anchor" href="#_4-准备证书和账号" aria-label="Permalink to &quot;4. 准备证书和账号&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>准备内容</th></tr></thead><tbody><tr><td>证书方式</td><td>默认 <code>self-signed</code>，由安装器生成自签名证书；选择 <code>provided</code> 时，由维护人员准备证书文件、私钥文件和按需提供的 CA 文件</td></tr><tr><td>自带证书文件</td><td>准备服务器上的绝对路径；证书需与私钥匹配、处于有效期内、信任链有效，并覆盖公共访问地址和服务器内网仓库地址</td></tr><tr><td>平台超级管理员用户名</td><td>默认 <code>admin</code>，用于管理入口</td></tr><tr><td>平台超级管理员初始密码</td><td>由安装人员设置，输入两次，实际长度为 8–72 字节</td></tr></tbody></table><p>建议密码使用 8–72 个 ASCII 字符，例如英文字母、数字和半角符号。终端当前用“字符”描述长度，但实际按字节校验；中文等字符通常占多个字节，不能按屏幕上的字符数量推算是否符合限制。</p><p>平台超级管理员与组织管理员是两种账号。安装时设置的密码只用于平台超级管理员；默认组织管理员的密码需要在<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>时另行设置。</p><h2 id="成功确认" tabindex="-1">成功确认 <a class="header-anchor" href="#成功确认" aria-label="Permalink to &quot;成功确认&quot;">​</a></h2><p>开始安装前，应能确认以下事项。</p><ul><li>服务器、系统权限、磁盘余量和完整安装包已经核对。</li><li>公共地址、两个端口和程序存放位置已经确定。</li><li>证书方式明确，自带证书所需文件已由维护人员核对。</li><li>平台超级管理员信息有明确的保管与交接对象。</li></ul><h2 id="未满足条件时" tabindex="-1">未满足条件时 <a class="header-anchor" href="#未满足条件时" aria-label="Permalink to &quot;未满足条件时&quot;">​</a></h2><p>系统不符、磁盘余量不足、端口冲突或证书材料不全时，先交给服务器维护人员处理。不要为腾出空间删除现有平台数据，也不要在不清楚影响范围时同意替换服务器已有的运行环境。</p><p>可观察到的提示及处理边界见<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>条件满足后，继续<a href="/induframe-docs/zh/installation/install.html">安装中心</a>。填写时需要逐项查询默认值，可打开<a href="/induframe-docs/zh/reference/install-options.html">安装参数</a>。</p>',31)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
